import InvoiceAI from '@horizonpay/invoice-ai'

const invoiceai = new InvoiceAI() // reads INVOICE_AI_API_KEY

// Retries reuse one Idempotency-Key; pass { idempotencyKey } to set your own.
const invoice = await invoiceai.invoices.create({
  customer: 'cus_Nf3kQ8pR2mX7vB1cT9wL4sZ6',
  currency: 'USD',
  due_date: '2026-10-22',
  description: 'Consulting retainer.',
  items: [
    { price: 'price_Jc5Tn8Wq1Ze6Ra3Ym9Ub2Gs7', quantity: 1 },
    {
      description: 'Onboarding workshop',
      quantity: 1,
      unit: 'NOS',
      unit_amount: 50000,
      tax_rate: 0,
    },
  ],
})
console.log(invoice.id, invoice.status)

